import React, { useEffect, useState } from "react";
import axios from "axios";

export default function Translate({ text }) {
  const [translated, setTranslated] = useState("");

  useEffect(() => {
    if (!text.trim()) {
      setTranslated("");
      return;
    }

    axios
      .get("https://dictionary.yandex.net/api/v1/dicservice.json/lookup", {
        params: {
          key: "dict.1.1.20261021T184653Z.f1e3b43d1ce683ed.d0e0f26a0740cf02ac0e5ec6b706a89c45b4e427",
          lang: "ru-en",
          text: text.trim(),
        },
      })
      .then(({ data }) => {
        setTranslated(data.def?.[0]?.tr?.[0]?.text || "Перевод не найден");
      })
      .catch(() => {
        setTranslated("Не удалось получить перевод");
      });
  }, [text]);

  return (
    <div>
      <h1>{translated}</h1>
      <a href="https://api.yandex.com/dictionary">
        Powered by Yandex.Dictionary
      </a>
    </div>
  );
}